 ```javascript
import { MeshBasicNodeMaterial, PlaneGeometry, Group, Mesh, Vector3, SRGBColorSpace } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = items.find((i) => i?.text) ?? { text: 'Journal 2', role: 'headline', typography: { fontSize: 39 } };
  const label = String(textItem.text);

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const width = 1.6;
  const height = 1.0;

  const group = new Group();
  group.name = config.id || 'journal-card-2-label';

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({ transparent: true, opacity: 1 });
  const card = new Mesh(geometry, material);
  group.add(card);

  const edgeGeometry = new PlaneGeometry(width * 1.06, height * 1.06);
  const edgeMaterial = new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0,
    depthWrite: false
  });
  const edge = new Mesh(edgeGeometry, edgeMaterial);
  edge.position.z = -0.005;
  edge.renderOrder = -1;
  group.add(edge);

  const fontSize = (textItem.typography?.fontSize ?? 39) / 300;
  const textObj = ctx.fontAtlas.createText(label, {
    fontSize,
    color: colors.paper,
    align: 'center'
  });
  textObj.position.set(0, 0, 0.01);
  group.add(textObj);

  const sp = config.scenePosition ?? { x: 0, y: 1, z: 0.06 };
  const basePos = new Vector3(sp.x, sp.y, sp.z);

  const effects = [];
  for (const primitive of config.cinematicPrimitives ?? []) {
    const handler = ctx.primitives[primitive.name];
    if (typeof handler === 'function') {
      effects.push(handler(group, primitive.params ?? {}));
    }
  }

  let hovered = false;

  function setHover(active) {
    hovered = active;
    gsap.to(group.position, {
      z: active ? basePos.z + 0.15 : basePos.z,
      duration: 0.35,
      ease: 'power2.out',
      overwrite: true
    });
    gsap.to(edgeMaterial, {
      opacity: active ? 0.85 : 0,
      duration: 0.25,
      ease: 'power2.out',
      overwrite: true
    });
  }

  function pointerEnter() {
    setHover(true);
  }

  function pointerLeave() {
    setHover(false);
  }

  function click() {
    ctx.emit('hub-journal.select', { id: config.id, source: 'journal-card-2-label' });
    gsap.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
      yoyo: true,
      repeat: 1,
      overwrite: true
    });
  }

  group.userData.handlers = {
    hover: pointerEnter,
    hoverOut: pointerLeave,
    click
  };

  group.userData.cleanup = () => {
    effects.forEach((e) => {
      if (e && typeof e.cleanup === 'function') e.cleanup();
      if (e && e.timeline) e.timeline.kill();
    });
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(edgeMaterial);
    if (material.map) material.map.dispose();
    material.dispose();
    edgeMaterial.dispose();
    geometry.dispose();
    edgeGeometry.dispose();
    group.remove(textObj);
  };

  ctx.textureLoader.loadTexture(config.imageUrl ?? '/prism-mock/home/nodes/feature-card.png')
    .then((tex) => {
      if (!tex) return;
      tex.colorSpace = SRGBColorSpace;
      material.map = tex;
      material.needsUpdate = true;
    })
    .catch(() => {
      material.color = new (ctx.THREE.Color)(colors.surface);
    });

  return group;
}
